export default {
  extends: ['@commitlint/config-conventional'],
  plugins: [
    {
      rules: {
        'refs-footer-required': ({ footer }) => {
          const refsPattern = /^Refs: #\d+(\s+#\d+)*$/m;
          const valid = refsPattern.test(footer ?? '');
          return [
            valid,
            'Commit must include a Refs footer with at least one work item (e.g., "Refs: #1234")',
          ];
        },
      },
    },
  ],
  rules: {
    'refs-footer-required': [2, 'always'],
  },
};
